<section class="page-hero page-hero-compact"><div class="container"><p class="eyebrow eyebrow-light">PENCARIAN WEBSITE</p><h1>Temukan informasi.</h1><form class="hero-search-form" action="/cari" method="get"><label class="sr-only" for="search-query">Kata kunci</label><input id="search-query" type="search" name="q" value="<?= e($query) ?>" placeholder="Ketik kata kunci…"><button class="button button-gold">Cari</button></form></div></section><section class="section-block"><div class="container"><h2 class="results-heading"><?= $query !== '' ? 'Hasil pencarian untuk “' . e($query) . '”' : 'Masukkan kata kunci pencarian' ?></h2><?php if ($results): ?><div class="search-results"><?php foreach ($results as $item): ?><a class="search-result" href="<?= e(content_url($item['type'], $item['slug'])) ?>"><span class="eyebrow"><?= e($item['type']) ?> · <?= e(format_date($item['publish_at'] ?: $item['created_at'])) ?></span><strong><?= e($item['title']) ?></strong><p><?= e(excerpt($item['excerpt'] ?: '', 180)) ?></p></a><?php endforeach; ?></div><?php elseif ($query !== ''): ?><div class="empty-state"><h3>Informasi belum ditemukan.</h3><p>Coba gunakan kata kunci yang lebih singkat atau jelajahi menu publikasi sekolah.</p></div><?php endif; ?></div></section>
